all.example:
for (const horse of kcds.characters.Horse.all()) {
  console.info(`${horse.name}: ${horse.owner?.nickname ?? 'no owner'}`);
}

all.exampleCs:
foreach (var horse in Horse.All())
{
    Log.Info($"{horse.Name}: {((string.IsNullOrEmpty(horse.Owner?.Nickname) ? "no owner" : horse.Owner?.Nickname))}");
}

getById.example:
kcds.core.Events.fromClient('stable:call', (player, payload) => {
  const horse = kcds.characters.Horse.getById(Number(payload?.id));
  if (horse && horse.ownerId === player.id) {
    horse.moveTo(player.position, { speed: 'run' });
  }
});

getById.exampleCs:
Events.FromClient("stable:call", (Player player, JsValue payload) =>
{
    var horse = Horse.GetById(payload["id"].AsNumber());
    if (horse != null && horse.OwnerId == player.Id)
    {
        horse.MoveTo(player.Position, new { speed = "run" });
    }
});

spawn.example:
const { Horse } = kcds.characters;
const { Vector3 } = kcds.math;

const spot = player.position.clone().add(player.rotation.rotateVector(new Vector3(0, 3, 0)));
const pebbles = Horse.spawn(spot, player.rotation, '', 'Pebbles', 'horse_noble05');
pebbles.setDimension(player.dimension);
pebbles.giveTo(player);
player.mount(pebbles);

spawn.exampleCs:
var spot = player.Position.Clone().Add(player.Rotation.RotateVector(new Vector3(0, 3, 0)));
var pebbles = Horse.Spawn(spot, player.Rotation, "", "Pebbles", "horse_noble05");
pebbles.SetDimension(player.Dimension);
pebbles.GiveTo(player);
player.Mount(pebbles);

