follow.example:
// The stable boy leads the horse out to its owner.
horse.follow(stableBoy, { radius: 2.5, speed: 'walk', rope: true });
kcds.core.Events.on('npcIntentDone', (npc) => {
  if (npc === stableBoy) {
    horse.hold();
  }
});

follow.exampleCs:
// The stable boy leads the horse out to its owner.
horse.Follow(stableBoy, new { radius = 2.5, speed = "walk", rope = true });
Events.On("npcIntentDone", (Npc npc) =>
{
    if (npc == stableBoy)
    {
        horse.Hold();
    }
});

